export const sum=(xs,fn=x=>x)=>xs.reduce((s,x)=>s+fn(x),0);
export function buildRows(){const rows=[];for(const month of [8,9]){for(let d=1;d<=(month===9?15:31);d++){const date=`2026-${String(month).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const weekend=[0,6].includes(new Date(date+'T12:00:00Z').getUTCDay());projects.forEach((p,i)=>{const variation=1+Math.sin(d*1.7+i)*.085;const season=month===9?1.04:1;const usage=(weekend&&p.env!=='Production')?.65:weekend?.90:1;p.services.forEach(([service,weight],j)=>{let cost=p.base*weight*variation*season*usage;if(month===9&&p.id==='atlas-analytics-prod'&&service==='BigQuery'&&d>=11)cost+=[1920,1740,1490,1810,1660][d-11];const net=Math.round(cost*100);const gross=Math.round(net/0.98);rows.push({date,month,day:d,project:p.id,service,cost:net,listCost:gross,credits:net-gross,region:p.region,environment:p.env});});});}}return rows;}
export const rows=buildRows();
