export function allocation(input,owners={},method='usage'){
const direct=Object.fromEntries(teams.map(t=>[t,0]));let shared=0,unallocated=0;
for(const r of input){const p=projects.find(p=>p.id===r.project);const owner=owners[p.id]||p.team;if(owner==='Partagé')shared+=r.cost;else if(direct[owner]!==undefined)direct[owner]+=r.cost;else unallocated+=r.cost;}
const totalDirect=sum(Object.values(direct));const weights=teams.map(t=>method==='equal'?1:direct[t]);const denom=sum(weights);const raw=weights.map(w=>denom?shared*w/denom:0);const shares=raw.map(Math.floor);let remainder=denom?shared-sum(shares):0;const order=raw.map((v,i)=>({i,f:v-Math.floor(v)})).sort((a,b)=>b.f-a.f);for(let n=0;n<remainder;n++)shares[order[n%order.length].i]++;
return{items:teams.map((team,i)=>({team,direct:direct[team],shared:shares[i],total:direct[team]+shares[i]})),shared,unallocated:unallocated+(denom?0:shared),total:sum(input,r=>r.cost),totalDirect};
}
export function commitment(base,usage,commitment,discount){const actual=base*usage/100,engaged=base*commitment/100,fee=engaged*(1-discount/100),overflow=Math.max(actual-engaged,0),cost=fee+overflow;return{actual,engaged,fee,overflow,cost,saving:actual-cost,unused:Math.max(engaged-actual,0)*(1-discount/100),utilization:engaged?Math.min(actual/engaged,1)*100:100};}
